require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch();if(!$u){flash('danger','User not found.');redirect('users/index.php');}$pageTitle='Edit User';$activeMenu='users';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$first=trim($_POST['first_name']);$last=trim($_POST['last_name']);$email=trim($_POST['email']);$role=(int)$_POST['role_id'];$dept=(int)($_POST['department_id']??0)?:null;$active=isset($_POST['is_active'])?1:0;$pw=$_POST['new_password']??'';if($first===''||$last===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$role)$errors[]='Complete all required fields.';if($pw!==''&&strlen($pw)<8)$errors[]='New password must be at least 8 characters.';if($id===(int)current_user()['id']&&!$active)$errors[]='You cannot disable your own account.';if(!$errors){try{if($pw!==''){db()->prepare('UPDATE users SET first_name=?,last_name=?,email=?,role_id=?,department_id=?,is_active=?,password_hash=?,updated_at=NOW() WHERE id=?')->execute([$first,$last,$email,$role,$dept,$active,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{db()->prepare('UPDATE users SET first_name=?,last_name=?,email=?,role_id=?,department_id=?,is_active=?,updated_at=NOW() WHERE id=?')->execute([$first,$last,$email,$role,$dept,$active,$id]);}log_activity('UPDATE','Users','Updated '.$u['username']);flash('success','User updated.');redirect('users/index.php');}catch(PDOException $e){$errors[]='Email is already in use.';}}}$roles=db()->query('SELECT id,name FROM roles ORDER BY id')->fetchAll();$departments=departments();require ROOT_PATH.'/includes/header.php';?>
